    "workers.kpi.uniqueShort":   "noyob",
    "workers.tip.onList":        "Kuniga o'rtacha necha kishi brigadir ro'yxatida turgani — kelgani ham, kelmagani ham. Davomat jadvalida har bir xodim, ishga chiqqan-chiqmaganidan qat'i nazar, qayd etiladi.",
