    "workers.shortfall":       "Yetishmovchilik",
    "workers.hm.none":         "tasdiqlangan kun yo'q",
    "workers.info.composition":"Har bir bo'lak — bitta lavozimning ulushi; markazda umumiy son. Sonlar — tasdiqlangan kunlar bo'yicha kuniga o'rtacha. «Jami / Zagruzka» qaysi lavozimlar sanalishini, «Ro'yxatda / Kelgan / Farq» esa ro'yxatdagilar, ishga chiqqanlar yoki ular orasidagi farq (kelmaganlar) ko'rsatilishini belgilaydi. Brigadir bo'yicha sonlar quyidagi jadvalda.",
    "workers.rosterVsPresent": "Rejaga nisbatan davomat, %",
    "workers.roleShare":       "Lavozimlar ulushi",
    "workers.info.treemap":    "Har bir blok — bitta brigadir; o'lchami ishchilar soniga qarab, har bir brigadir o'z rangida. Sonlar — tasdiqlangan kunlar bo'yicha kuniga o'rtacha. «Jami / Zagruzka» qaysi lavozimlar sanalishini, «Ro'yxatda / Kelgan / Farq» esa ro'yxatdagilar, ishga chiqqanlar yoki ular orasidagi farq (kelmaganlar) ko'rsatilishini belgilaydi. Katta blok = ko'proq ishchi.",
