    "workers.perDay":          "kuniga o'rtacha",
    "workers.info.rosterVsPresent":"Har bir brigadir uchun haqiqiy davomatning rasmiy (rejadagi) xodimlar soniga nisbati: kunlik o'rtacha kelgan ÷ reja × 100%. Svetofor ranglari: yashil — to'liq ta'minlangan (≥95%), sariq — o'rtacha yetishmovchilik (85–95%), qizil — jiddiy yetishmovchilik (<85%). Faqat rasmiy ma'lumoti bor brigadirlar ko'rsatiladi.",
    "workers.info.roleMix":    "Har bir nur — bitta lavozim. To'ldirilgan shakl tanlangan brigadirning lavozimlar soni; kulrang shakl — barcha brigadirlar bo'yicha o'rtacha. Ikki shaklni solishtiring.",
    "workers.info.trend":      "Kunlar bo'yicha ishchilar, lavozim bo'yicha ajratilgan va ustma-ust joylashgan. «Ro'yxatda» ro'yxatdagilarni, «Kelgan» ishga chiqqanlarni, «Farq» esa kelmaganlarni ko'rsatadi. Oyna doim kamida 7 kun.",
    "workers.info.heatmap":    "Qatorlar — brigadirlar, ustunlar — kunlar. Har bir katakcha — o'sha kuni ro'yxatdagilarning necha foizi ishga chiqqani (kelgan ÷ ro'yxatdagi). Yashil — deyarli hamma kelgan (≥90%), sariq — 75–90%, qizil — 75% dan kam. Katakcha ustiga kursorni olib borsangiz aniq sonlar chiqadi; bo'sh katakcha — kun tasdiqlanmagan.",
    "workers.info.original":   "Sonlar DASTLABKI brigadir bo'yicha: almashinuv bo'yicha berilgan ishchi kun boshida qaysi brigadirda bo'lsa, o'sha yerda hisoblanadi, soatlarini nolga tushirgan «vazifaga» almashinuv esa baribir kelgan deb sanaladi. Tabelning o'zi o'zgarmaydi — u ishchi kunni aslida qayerda o'tkazganini ko'rsatadi.",
    "workers.info.byDay":      "Har kunlik ustunlar: ko'k — odam almashinuvi so'rovlari, binafsha — lavozim o'zgartirish so'rovlari.",
    "workers.info.targets":    "Almashtirilgan ishchilar qayerga yuborilgani — qabul qiluvchi brigadir (→) yoki vazifa. Uzunroq ustun = ko'proq ishchi ko'chirilgan.",
    "workers.info.transitions":"Qatorlar — eski lavozim, ustunlar — yangi lavozim. Har katakdagi son o'sha eski lavozimdan yangi lavozimga qancha ishchi o'tganini bildiradi.",
