    "admin.ltasks.criteriaHint": "AI isbot rasmlarini shu talabga solishtiradi. Bo'sh qoldirilsa — yuqori darajadagi talab qo'llanadi. Liderlar bu matnni /leaders «Vazifalar» bo'limida vazifa tavsifi sifatida ko'radi.",
    "admin.ltasks.window": "Rasm olinadigan vaqt",
    "admin.ltasks.windowHint": "Isbot rasmi shu oraliqda olingan bo'lishi kerak — AI shunga qarab tekshiradi va bot liderga shu vaqtni ko'rsatadi. Bo'sh qoldirilsa yuqori daraja, undan keyin smena vaqti qo'llanadi. Tugash vaqti boshlanishdan kichik bo'lsa — oyna yarim tundan o'tadi.",
