    "admin.ltasks.perTaskHint.off": "Hozirgi tartib: lider hamma vazifani to'ldiradi va oxirida «KUNNI YOPISH» tugmasini bosadi. Tekshiruv kun yopilgandan keyin boshlanadi.",
    "admin.ltasks.perTaskHint.on":  "Liderda «Kunni yopish» tugmasi bo'lmaydi. Har bir vazifa alohida yopiladi: yopilgan vazifa darhol tekshiruvga ketadi va uni boshqa o'zgartirib bo'lmaydi. Oxirgi vazifa yopilganda kun o'zi yopiladi.",
    "admin.ltasks.perTaskWarn":     "⚠️ Yopilgan vazifani hech kim, hech qachon qayta ocholmaydi — na lider, na administrator. Vazifa o'z deadline'ida avtomatik yopiladi.",
    "admin.ltasks.botFrom":         "Bot topshiriqlari qaysi kundan hisoblanadi",
    "admin.ltasks.botFromHint.off": "Hozir: brigada botga vazifa yopishi bilan o'sha kun hisobga olinadi. Agar brigada endi o'rganayotgan bo'lsa, o'rgangan kunlari hisobga olinmasligi uchun sanani tanlang.",
    "admin.ltasks.botFromHint.on":  "{date} sanasidan boshlab bot yozuvlari hisoblanadi. Undan oldingi kunlarda brigada botni o'rganadi: reyting, ball va kun hisoboti eski tartibda — qo'lda to'ldirilgan jadvaldan olinadi. Mashq kunlaridagi rasmlar sun'iy intellektga umuman yuborilmaydi va hech kimga ball hisoboti bormaydi.",
