    "workers.kpi.uniqueShort":   "ноёб",
    "workers.tip.onList":        "Кунига ўртача неча киши бригадир рўйхатида тургани — келгани ҳам, келмагани ҳам. Давомат жадвалида ҳар бир ходим, ишга чиққан-чиқмаганидан қатъи назар, қайд этилади.",
    "workers.tip.came":          "Рўйхатдагилардан кунига ўртача нечтаси ишга чиққани (ишлаган соати нолдан катта).",
    "workers.tip.absent":        "Кунига ўртача неча киши рўйхатда туриб ишга чиқмагани (рўйхатдагилар − келганлар). Қавс ичида шундан нечтаси таътилда экани.",
    "workers.shortfall":       "Етишмовчилик",
    "workers.hm.none":         "тасдиқланган кун йўқ",
    "workers.info.composition":"Ҳар бир бўлак — битта лавозимнинг улуши; марказда умумий сон. Сонлар — тасдиқланган кунлар бўйича кунига ўртача. «Жами / Загрузка» қайси лавозимлар саналишини, «Рўйхатда / Келган / Фарқ» эса рўйхатдагилар, ишга чиққанлар ёки улар орасидаги фарқ (келмаганлар) кўрсатилишини белгилайди. Бригадир бўйича сонлар қуйидаги жадвалда.",
    "workers.rosterVsPresent": "Режага нисбатан давомат, %",
    "workers.roleShare":       "Лавозимлар улуши",
    "workers.info.treemap":    "Ҳар бир блок — битта бригадир; ўлчами ишчилар сонига қараб, ҳар бир бригадир ўз рангида. Сонлар — тасдиқланган кунлар бўйича кунига ўртача. «Жами / Загрузка» қайси лавозимлар саналишини, «Рўйхатда / Келган / Фарқ» эса рўйхатдагилар, ишга чиққанлар ёки улар орасидаги фарқ (келмаганлар) кўрсатилишини белгилайди. Катта блок = кўпроқ ишчи.",
    "workers.tmAll":           "Жами",
    "workers.tmZagruzka":      "Загрузка",
    "workers.tmUnit":          "ишчи",
    "workers.msRoster":        "Рўйхатда",
    "workers.msCame":          "Келган",
    "workers.msDiff":          "Фарқ",
    "workers.perDay":          "кунига ўртача",
    "workers.info.rosterVsPresent":"Ҳар бир бригадир учун ҳақиқий давоматнинг расмий (режадаги) ходимлар сонига нисбати: кунлик ўртача келган ÷ режа × 100%. Светофор ранглари: яшил — тўлиқ таъминланган (≥95%), сариқ — ўртача етишмовчилик (85–95%), қизил — жиддий етишмовчилик (<85%). Фақат расмий маълумоти бор бригадирлар кўрсатилади.",
    "workers.info.roleMix":    "Ҳар бир нур — битта лавозим. Тўлдирилган шакл танланган бригадирнинг лавозимлар сони; кулранг шакл — барча бригадирлар бўйича ўртача. Икки шаклни солиштиринг.",
    "workers.info.trend":      "Кунлар бўйича ишчилар, лавозим бўйича ажратилган ва устма-уст жойлашган. «Рўйхатда» рўйхатдагиларни, «Келган» ишга чиққанларни, «Фарқ» эса келмаганларни кўрсатади. Ойна доим камида 7 кун.",
    "workers.info.heatmap":    "Қаторлар — бригадирлар, устунлар — кунлар. Ҳар бир катакча — ўша куни рўйхатдагиларнинг неча фоизи ишга чиққани (келган ÷ рўйхатдаги). Яшил — деярли ҳамма келган (≥90%), сариқ — 75–90%, қизил — 75% дан кам. Катакча устига курсорни олиб борсангиз аниқ сонлар чиқади; бўш катакча — кун тасдиқланмаган.",
    "workers.info.original":   "Сонлар ДАСТЛАБКИ бригадир бўйича: алмашинув бўйича берилган ишчи кун бошида қайси бригадирда бўлса, ўша ерда ҳисобланади, соатларини нолга туширган «вазифага» алмашинув эса барибир келган деб саналади. Табелнинг ўзи ўзгармайди — у ишчи кунни аслида қаерда ўтказганини кўрсатади.",
    "workers.info.byDay":      "Ҳар кунлик устунлар: кўк — одам алмашинуви сўровлари, бинафша — лавозим ўзгартириш сўровлари.",
    "workers.info.targets":    "Алмаштирилган ишчилар қаерга юборилгани — қабул қилувчи бригадир (→) ёки вазифа. Узунроқ устун = кўпроқ ишчи кўчирилган.",
    "workers.info.transitions":"Қаторлар — эски лавозим, устунлар — янги лавозим. Ҳар катакдаги сон ўша эски лавозимдан янги лавозимга қанча ишчи ўтганини билдиради.",
