    "lostWorkers.intro": "Тасдиқланган «бригадирга ўтказиш» ҳужжатидан кейин давомат қайта юкланган бўлса, ўтказилган ходимнинг қатори қабул қилувчи бригадирдан ўчиб кетади ва юборувчига ҳам қайтмайди. Натижада одам ишга келган бўлса ҳам, платформада ҳеч қаерда кўринмайди. Бу рўйхат — фақат ўқиш учун: ҳеч нарса ўзгартирилмайди. Қаторни тиклаш ўша куннинг загрузка ва KPI рақамларини оширади, шунинг учун аввал ҳажми кўрилади.",
