    "reconcile.intro": "Ҳар бир кун учун иккита рўйхат солиштирилади: юкланган файл ким ишлаган деса (белгиланган ва бригадирга бириктирилган ячейкалар) ва платформа ҳозир кимни кўрсата олса. Фарқи — йўқолган одам. Сабаби муҳим эмас: алмашинув, ячейка белгиси олиб ташлангани, кун ўчирилгани ёки ёпиқ кун — ҳаммаси шу ерда чиқади.",
