    "admin.ltasks.botFromHint.off": "Ҳозир: бригада ботга вазифа ёпиши билан ўша кун ҳисобга олинади. Агар бригада энди ўрганаётган бўлса, ўрганган кунлари ҳисобга олинмаслиги учун санани танланг.",
