    "workers.info.rosterVsPresent":"Для каждого бригадира — доля фактической явки от официальной (штатной) численности: среднесуточная явка ÷ штат × 100%. Цвет по светофору: зелёный — полная укомплектованность (≥95%), жёлтый — умеренный недобор (85–95%), красный — серьёзный недобор (<85%). Показаны только бригадиры, по которым есть официальные данные.",
    "workers.info.roleMix":    "Каждый луч — должность. Заполненная фигура — число рабочих выбранного бригадира; серая фигура — среднее по всем бригадирам. Сравните две фигуры.",
