    "workers.info.heatmap":    "Строки — бригадиры, столбцы — дни. Ячейка — какая доля списка вышла на работу в этот день (пришли ÷ в списке). Зелёный — вышли почти все (≥90%), жёлтый — 75–90%, красный — меньше 75%. При наведении на ячейку видны сами числа; пустая ячейка — день не подтверждён.",
    "workers.info.original":   "Числа — по ИСХОДНОМУ бригадиру: работник, отданный по обмену, считается у того, к кому он был приписан в начале дня, а обмен «на задачу», обнуливший часы, всё равно считается явкой. Сам табель не меняется — он показывает, где работник фактически провёл день.",
