    "admin.ltasks.botFromHint.on":  "С {date} засчитываются записи из бота. До этой даты бригада тренируется: рейтинг, баллы и отчёт за день берутся по-старому — из заполненной вручную таблицы. Фото тренировочных дней вообще не отправляются на проверку ИИ, и отчёт с баллами никому не приходит.",
