    "workers.info.composition":"Each slice is one role's share; the center shows the total. Numbers are per-day averages over the confirmed days. «Total / Workload» picks which roles count, «On list / Came / Difference» picks whether you see everyone on the list, only those who turned up, or the gap between the two (those who did not come). Per-brigadir counts are in the table below.",
