    "reconcile.title": "In the file, not on the platform",
    "reconcile.intro": "For each day two lists are compared: who the uploaded file says worked (ticked cells routed to a supervisor) and who the platform can still show. The difference is a lost worker. The cause does not matter — an exchange, an unticked cell, a deleted day, a closed day: all of them land here.",
