    "reconcile.footnote": "«Lost» — the row was written and then deleted; that is the real problem. «Not saved» — the cell is ticked but never projected (usually a closed day): pressing Save, or re-opening the day, writes it. This check runs automatically every 12 hours and DMs admins on Telegram whenever anyone is lost.",
